      const medium = moves.length ? motionDuration(container, '--ds-dur-medium') : 0;
      const slow = moves.length ? motionDuration(container, '--ds-dur-slow') : 0;
      const ranked = moves.map((move) => ({ move, distance: Math.hypot(move.dx, move.dy) }))
