        if (to === undefined) return;
        event.preventDefault();
        if (to < 0 || to >= order.length || to === index) return;
        const before = order.slice();
        flip(list, () => place(item, to > index ? order[to].nextSibling : order[to]), { items: selector });
        changed(before);
        say(item);
