      if (!pieces.length) pieces.push([DURATION_UNITS[floor][0], 0]);
      const formatted = pieces.map(([unit, count], index) => numberFormat(locale, { style: 'unit', unit, unitDisplay: style }).format(negative && index === 0 ? -count : count));
