          return { ...input, type: spec.type, series: spec.series.map((entry) => ({ ...((input.series ?? [])[spec.series.indexOf(entry)] ?? {}), name: entry.name, values: [...entry.values], visible: entry.visible })), labels: [...spec.labels] };
