        // certificate, say) is the value, pasted as the field takes it.
        if (isKey ? !(text.includes('\n') || text.includes('=')) : !(text.includes('\n') && assignments(text))) return;
        const pairs = parse(text);
        if (!pairs.length) return;
        event.preventDefault();
