        const chip = /** @type {Element} */ (event.target)?.closest?.('.ds-chip[data-ds-taginput-tag]');
        if (!chip || event.defaultPrevented) return;
        const list = chips();
        const at = list.indexOf(/** @type {HTMLButtonElement} */ (chip));
        const k = event.key;
        if (k === 'ArrowLeft') focusChip(at - 1, event);
