          frame = 0;
          if (phase !== 'open' || !trigger) return;
          const rect = trigger.getBoundingClientRect();
          const gone = !trigger.isConnected || rect.bottom <= 0 || rect.right <= 0 || rect.top >= view.innerHeight || rect.left >= view.innerWidth;
          if (gone) hide();
