    /** A day of the calendar in ms, for day counts only (never a timing). */
    const DAY_LENGTH = 864e5;

    /** The events a controller's on() takes. */
    const EVENTS = new Set(['earlier']);

    /** A locale the engine takes, else undefined (its default). */
